  function parseCsvRows(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'&&text[i+1]==='"'){field+='"';i++;}else if(ch==='"')quoted=false;else field+=ch;}else if(ch==='"'&&field==='')quoted=true;else if(ch===','){row.push(field);field='';}else if(ch==='\n'){row.push(field.replace(/\r$/,''));if(row.some(value=>value.trim()))rows.push(row);row=[];field='';}else field+=ch;}if(quoted)throw new Error('CSV has an unclosed quoted field.');if(field.length||row.length){row.push(field.replace(/\r$/,''));if(row.some(value=>value.trim()))rows.push(row);}return rows;}
